13	/**
14	 * Step of {@code POST /api/owners}: when the request opts in with {@code sharesHousehold: true},
15	 * assigns a stable shared {@code householdId} to the new owner and to every existing owner sharing
16	 * its household (same last name and address, compared case-insensitively with collapsed
17	 * whitespace — the same comparison {@link RequireUniqueHousehold} uses).
18	 *
19	 * <p>The identifier is derived deterministically from the normalised last name and address, so all
20	 * members of a household resolve to the same value regardless of creation order, and the existing
21	 * members are updated in place so they carry it too. A request that does not set the flag is left
22	 * untouched (no household). Runs after {@link BuildOwner}, under the write transaction.
23	 */
24	public class AssignHouseholdId {
25	
26	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
27	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return;
29	        }
30	        String lastName = normalize(request.getLastName());
31	        String address = AddressNormalizer.normalize(request.getAddress());
32	        String householdId = deriveHouseholdId(lastName, address);
33	        owner.setHouseholdId(householdId);
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (lastName.equals(normalize(existing.getLastName()))
36	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))
37	                    && !householdId.equals(existing.getHouseholdId())) {
38	                existing.setHouseholdId(householdId);
39	                ownerRepository.save(existing);
40	            }
41	        }
42	    }
